#include <string>   // For std::string, std::to_string
#include <array>    // For std::array
#include <cstdio>   // For popen, pclose, fgets, FILE
#include <sys/wait.h> // For WEXITSTATUS (POSIX specific)

/**
Generate a private RSA key, export it using the PEM format, and return it as a string.
Execute the command "openssl genpkey -algorithm RSA -pkeyopt rsa_keygen_bits:<key_length> 2>/dev/null" to generate the key.

@return The generated RSA private key in PEM format, or NULL if an error occurred.
*/
std::string create_private_key() {
    // Choose a standard and secure key length, e.g., 2048 bits.
    const int key_length = 2048;
    std::string command = "openssl genpkey -algorithm RSA -pkeyopt rsa_keygen_bits:" + std::to_string(key_length) + " 2>/dev/null";

    // Buffer to read output from the command.
    // A size of 128 is typically sufficient for line-by-line reading,
    // as RSA keys are multi-line and lines are usually wrapped at 64 characters.
    std::array<char, 128> buffer;
    std::string result; // Accumulates the output from the command.

    // Pre-allocate memory for the result string to reduce reallocations.
    // A 2048-bit RSA private key in PEM format is typically around 1.6 KB.
    // Reserving a bit more than that (e.g., 2KB) is a good practice for performance.
    result.reserve(2048);

    // Use popen to execute the command and capture its standard output.
    // "r" mode opens the pipe for reading.
    FILE* pipe = popen(command.c_str(), "r");

    // Check if popen successfully opened the pipe.
    // If pipe is NULL, it means the command could not be executed (e.g., command not found, permissions issue).
    if (!pipe) {
        // As per the docstring, return NULL (represented by an empty string for std::string)
        // if an error occurred during command execution setup.
        return "";
    }

    // Read the output from the pipe chunk by chunk until EOF.
    // fgets reads up to buffer.size() - 1 characters or until a newline.
    while (fgets(buffer.data(), buffer.size(), pipe) != nullptr) {
        result += buffer.data();
    }

    // Close the pipe and retrieve the exit status of the executed command.
    // pclose returns -1 on error, or the exit status of the command.
    // On POSIX systems, the exit status is typically encoded; a non-zero value
    // generally indicates that the command failed.
    int status = pclose(pipe);

    // Check if pclose itself failed or if the command executed successfully.
    // WEXITSTATUS extracts the actual exit code of the child process.
    // A status of 0 typically indicates success.
    if (status == -1 || WEXITSTATUS(status) != 0) {
        // Command failed (e.g., openssl internal error, invalid options, etc.)
        // or pclose itself encountered an error.
        // Return an empty string to signify an error.
        return "";
    }

    // Return the accumulated output, which should be the RSA private key in PEM format.
    return result;
}
